  'admin.team.roleNote':     'Die Rolle entscheidet, was ein Konto auf der Plattform darf. Sie lässt sich bei einem aktiven Mitglied später über „Rolle ändern“ anpassen – Mitgliedschaft, Aufnahmedatum und Notiz bleiben dabei erhalten. Support und Nur Lesen dürfen die Verzeichnisse aller Kunden lesen (Fahrzeuge, Fahrer, Benutzer samt E-Mail-Adresse); die übrigen Geschäftsdaten eines Kunden nur in einer geöffneten Sitzung. Nur Inhaber dürfen das Team verwalten, Unternehmen freigeben oder sperren, Einstellungen ändern und das Protokoll lesen.',
