  'admin.team.grantedBy.unrecordedNote': '„Nicht erfasst“ unter „Erteilt von“ heißt: Diese Mitgliedschaft wurde eingerichtet, bevor die Plattform festhielt, wer Zugang erteilt – so entstanden die ersten Inhaber – oder außerhalb dieser Seite. Deshalb ist niemand dafür vermerkt. Wer über diese Seite aufgenommen wird, trägt immer das Konto, das den Zugang erteilt hat.',
