  // ── Engine messages (slice: i18n/engine-messages) ──────────────────────────
  // The pure modules under src/utils/ keep their German text and name one of
  // these keys beside it (`messageKey` / `<field>Key`). A screen renders
  // engineText(t, text, key, vars) from src/i18n/engineMessage.ts; the German
  // text is the fallback, so a missing key never shows a raw key.
